def parse(tree):
    val, left, right = [tree[0]], [-1], [-1]
    i, u = 1, 0
    while u < len(val) and i < len(tree):
        for kids in (left, right):
            if i < len(tree):
                x = tree[i]
                i += 1
                if x != -1:
                    kids[u] = len(val)
                    val.append(x)
                    left.append(-1)
                    right.append(-1)
        u += 1
    return val, left, right


from bisect import bisect_left


def orderStatisticOps(tree, ops):
    init = []
    if tree:
        init = parse(tree)[0]
    keys = sorted(set(init) | {x for t, x in ops if t == 0})
    m = len(keys)
    index = {v: i + 1 for i, v in enumerate(keys)}
    bit = [0] * (m + 1)

    def update(i, d):
        while i <= m:
            bit[i] += d
            i += i & -i

    def prefix(i):
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s

    top = 1
    while top * 2 <= m:
        top *= 2
    for v in init:
        update(index[v], 1)
    out = []
    for t, x in ops:
        if t == 0:
            update(index[x], 1)
        elif t == 1:
            update(index[x], -1)
        elif t == 2:
            pos, step, need = 0, top, x
            while step:
                nxt = pos + step
                if nxt <= m and bit[nxt] < need:
                    pos = nxt
                    need -= bit[nxt]
                step >>= 1
            out.append(keys[pos])  # pos is 0-based index of the answer
        else:
            out.append(prefix(bisect_left(keys, x)))
    return out
